-- The tournament seam: claims, fixtures, published results and disputes.
--
-- 0006 owns match_organizer_claims and official_scorer_assignments; 0008 owns
-- the tournament/fixture columns on matches; 0014 joins them. This suite proves
-- the join behaves: a fixture can only be generated by the member who claimed
-- the tournament, a scorer assigned through the tournament can score the linked
-- match without any extra grant, and the organizer's device can read back the
-- official results it needs to advance a draw - nothing more.
--
-- Members: Ayesha claims T-TOUR, Sana and Omar play, Bilal is a scorer who
-- declines, Dania is an uninvolved member.

begin;

create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;

select plan(33);

insert into auth.users
  (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
   created_at, updated_at, raw_app_meta_data, raw_user_meta_data)
values
  ('11111111-1111-1111-1111-111111111111',
   '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
   'ayesha@sportika.test', '$2a$10$notarealhashnotarealhashno', now(),
   now(), now(), '{"provider":"email","providers":["email"]}',
   '{"display_name":"Ayesha Khan"}'),
  ('22222222-2222-2222-2222-222222222222',
   '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
   'bilal@sportika.test', '$2a$10$notarealhashnotarealhashno', now(),
   now(), now(), '{"provider":"email","providers":["email"]}',
   '{"display_name":"Bilal Ahmed"}'),
  ('33333333-3333-3333-3333-333333333333',
   '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
   'sana@sportika.test', '$2a$10$notarealhashnotarealhashno', now(),
   now(), now(), '{"provider":"email","providers":["email"]}',
   '{"display_name":"Sana Iqbal"}'),
  ('44444444-4444-4444-4444-444444444444',
   '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
   'dania@sportika.test', '$2a$10$notarealhashnotarealhashno', now(),
   now(), now(), '{"provider":"email","providers":["email"]}',
   '{"display_name":"Dania Malik"}'),
  ('55555555-5555-5555-5555-555555555555',
   '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
   'omar@sportika.test', '$2a$10$notarealhashnotarealhashno', now(),
   now(), now(), '{"provider":"email","providers":["email"]}',
   '{"display_name":"Omar Raza"}');

create or replace function public._tap_id(p_title text)
returns uuid
language sql stable
security definer
set search_path = public
as $$ select id from public.matches where title = p_title $$;

create sequence if not exists public._tap_point_seq;
grant usage, select on sequence public._tap_point_seq to authenticated;

-- Plays out a match from whatever the point log already holds, so the fixture
-- assertions never depend on how many points the earlier steps happened to use.
create or replace function public._tap_finish(p_match uuid, p_side int)
returns void
language plpgsql
as $$
declare
  i int := 0;
begin
  while not (
    select is_complete from public.padel_match_state where match_id = p_match
  ) and i < 60 loop
    perform public.award_padel_point(
      p_match, p_side, 'tap-' || nextval('public._tap_point_seq')::text);
    i := i + 1;
  end loop;
end;
$$;

-- ── the claim ───────────────────────────────────────────────────────────────
set local role authenticated;
set local request.jwt.claims =
  '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aud":"authenticated"}';

select lives_ok(
  $$ select public.claim_tournament_organizer('T-TOUR') $$,
  'the first member to claim a tournament owns it');

select ok(
  (select organizer_id from public.match_organizer_claims
    where tournament_id = 'T-TOUR') = auth.uid(),
  'the claim records the caller derived from the session, never from an argument');

set local request.jwt.claims =
  '{"sub":"55555555-5555-5555-5555-555555555555","role":"authenticated","aud":"authenticated"}';
select throws_ok(
  $$ select public.claim_tournament_organizer('T-TOUR') $$,
  '42501', null, 'a second member cannot claim the same tournament');

set local request.jwt.claims =
  '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aud":"authenticated"}';
select lives_ok(
  $$ select public.claim_tournament_organizer('T-TOUR') $$,
  'the owner re-claiming their tournament is a no-op, not a takeover');

-- ── fixture generation ──────────────────────────────────────────────────────
select is(
  (select (tournament_id, fixture_id, visibility)::text
     from public.create_match(
       'padel', 'One set · first to 4', '{"setsToWin":1,"gamesToWinSet":4}'::jsonb,
       'TT1 final', 'Centre Court', '2026-05-01 18:00+05', 'invite',
       'Ayesha K', 'Sana I', 4, 'singles', null, 'T-TOUR', 'F1')),
  '(T-TOUR,F1,invite)',
  'a generated fixture keeps its tournament and fixture keys');

select throws_ok(
  $$ select public.create_match(
       'padel', 'One set · first to 4', '{"setsToWin":1,"gamesToWinSet":4}'::jsonb,
       'Half link', 'Court 2', '2026-05-01 19:00+05', 'public',
       'Ayesha K', 'Sana I', 4, 'singles', null, 'T-TOUR', null) $$,
  '22023', null, 'a tournament without a fixture is refused');

select throws_ok(
  $$ select public.create_match(
       'padel', 'One set · first to 4', '{"setsToWin":1,"gamesToWinSet":4}'::jsonb,
       'Half link two', 'Court 2', '2026-05-01 19:00+05', 'public',
       'Ayesha K', 'Sana I', 4, 'singles', null, null, 'F1') $$,
  '22023', null, 'a fixture without a tournament is refused');

select throws_ok(
  $$ select public.create_match(
       'padel', 'One set · first to 4', '{"setsToWin":1,"gamesToWinSet":4}'::jsonb,
       'TT1 duplicate', 'Centre Court', '2026-05-01 18:00+05', 'public',
       'Ayesha K', 'Sana I', 4, 'singles', null, 'T-TOUR', 'F1') $$,
  '23505', null, 'one draw slot can only ever hold one match');

select public.create_match(
  'padel', 'One set · first to 4', '{"setsToWin":1,"gamesToWinSet":4}'::jsonb,
  'TT2 semi', 'Court 2', '2026-05-01 19:00+05', 'public',
  'Ayesha K', 'Omar R', 4, 'singles', null, 'T-TOUR', 'F2');
select public.create_match(
  'padel', 'One set · first to 4', '{"setsToWin":1,"gamesToWinSet":4}'::jsonb,
  'TT3 walkover', 'Court 3', '2026-05-01 20:00+05', 'public',
  'Ayesha K', 'Sana I', 4, 'singles', null, 'T-TOUR', 'F3');

select public.invite_match_participant(public._tap_id('TT1 final'),
  '33333333-3333-3333-3333-333333333333', 1);
select public.invite_match_participant(public._tap_id('TT2 semi'),
  '55555555-5555-5555-5555-555555555555', 1);
select public.invite_match_participant(public._tap_id('TT3 walkover'),
  '33333333-3333-3333-3333-333333333333', 1);

set local request.jwt.claims =
  '{"sub":"33333333-3333-3333-3333-333333333333","role":"authenticated","aud":"authenticated"}';
select public.respond_match_invite(public._tap_id('TT1 final'), true);
select public.respond_match_invite(public._tap_id('TT3 walkover'), true);

set local request.jwt.claims =
  '{"sub":"55555555-5555-5555-5555-555555555555","role":"authenticated","aud":"authenticated"}';
select public.respond_match_invite(public._tap_id('TT2 semi'), true);

-- ── the scorer bridge, without the matches.scorer_id mirror ────────────────
set local request.jwt.claims =
  '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aud":"authenticated"}';

select ok(
  (public.assign_fixture_scorer('T-TOUR', 'F1',
     '55555555-5555-5555-5555-555555555555'))->'assignment'->>'status' = 'assigned',
  'assign_fixture_scorer writes an official_scorer_assignments row');

select is(
  (select scorer_id from public.matches where id = public._tap_id('TT1 final')),
  '55555555-5555-5555-5555-555555555555'::uuid,
  'the assignment is mirrored onto the linked match');

select ok(
  (select count(*)::int = 0 from public.published_fixture_results('T-TOUR')),
  'nothing is published yet, so the organizer gets no results back');

-- A pure tournament assignment authorizes scoring on its own: F2's
-- matches.scorer_id stays null, so only official_scorer_assignments can be
-- behind the point below.
select public.start_padel_match(public._tap_id('TT2 semi'), 0, 0);
select public.assign_official_scorer('T-TOUR', 'F2', '22222222-2222-2222-2222-222222222222');

set local request.jwt.claims =
  '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated","aud":"authenticated"}';
select ok(
  (public.award_padel_point(public._tap_id('TT2 semi'), 0, 'bridge-1'))->'state'->'points'
    = '[1, 0]'::jsonb,
  'a scorer assigned through the tournament can score the linked fixture');

-- ── playing and publishing the draw ─────────────────────────────────────────
set local request.jwt.claims =
  '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aud":"authenticated"}';
select is(
  ((public.revoke_fixture_scorer('T-TOUR', 'F2',
      '22222222-2222-2222-2222-222222222222'))->'matchId' is not null),
  true,
  'revoking a fixture scorer resolves the linked match even when the mirror is unset');

set local request.jwt.claims =
  '{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated","aud":"authenticated"}';
select throws_ok(
  $$ select public.award_padel_point(public._tap_id('TT2 semi'), 0, 'revoked-1') $$,
  '42501', null, 'a revoked tournament assignment stops scoring the fixture');

set local request.jwt.claims =
  '{"sub":"55555555-5555-5555-5555-555555555555","role":"authenticated","aud":"authenticated"}';
select public.start_padel_match(public._tap_id('TT1 final'), 0, 0);
select ok(
  (public.award_padel_point(public._tap_id('TT1 final'), 0, 'tt1-1'))->'state'->'points'
    = '[1, 0]'::jsonb,
  'the tournament-assigned scorer can score the fixture through the same RPC');

set local request.jwt.claims =
  '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aud":"authenticated"}';
select throws_ok(
  $$ select public.raise_match_dispute(public._tap_id('TT1 final'), 'nothing published yet') $$,
  '22023', null, 'a dispute needs a result to contest');

select public._tap_finish(public._tap_id('TT1 final'), 0);
select public.complete_padel_match(public._tap_id('TT1 final'));

select is(
  (select count(*)::int from public.published_fixture_results('T-TOUR')),
  0, 'a submitted but unpublished result is not offered to the draw');

select public.publish_match_result(public._tap_id('TT1 final'));

select is(
  (select (fixture_id, winner_side, side_values, published_at is not null)::text
     from public.published_fixture_results('T-TOUR')),
  '(F1,0,"[1, 0]",t)',
  'the published fixture result carries the keys a bracket needs');

select public.record_match_walkover(public._tap_id('TT3 walkover'), 0, 'no show');

select is(
  (select count(*)::int from public.published_fixture_results('T-TOUR')),
  2, 'a walkover counts as an official result for the draw');

select ok(
  (select count(*)::int = 1 and bool_and(winner_side in (0, 1))
     from public.published_fixture_results('T-TOUR')
    where fixture_id = 'F3'),
  'the walkover row names the advancing side');

select is(
  (select count(*)::int from public.published_fixture_results('T-OTHER')),
  0, 'another tournament key yields nothing');

set local request.jwt.claims =
  '{"sub":"44444444-4444-4444-4444-444444444444","role":"authenticated","aud":"authenticated"}';
select is(
  (select count(*)::int from public.published_fixture_results('T-TOUR')),
  1, 'a member sees the published result of a fixture that is public to them');

-- ── disputes over a published draw result ──────────────────────────────────
set local request.jwt.claims =
  '{"sub":"33333333-3333-3333-3333-333333333333","role":"authenticated","aud":"authenticated"}';

select throws_ok(
  $$ select public.raise_match_dispute(public._tap_id('TT1 final'), 'bad') $$,
  '22023', null, 'a dispute reason shorter than the UI minimum is refused');

select is(
  (select status from public.raise_match_dispute(
     public._tap_id('TT1 final'), 'the third set was recorded against the wrong side')),
  'open', 'a player can open a dispute against a published result');

set local request.jwt.claims =
  '{"sub":"44444444-4444-4444-4444-444444444444","role":"authenticated","aud":"authenticated"}';
select throws_ok(
  $$ select public.raise_match_dispute(
       public._tap_id('TT1 final'), 'I was not involved at all') $$,
  '42501', null, 'an uninvolved member cannot dispute a fixture result');

set local request.jwt.claims =
  '{"sub":"11111111-1111-1111-1111-111111111111","role":"authenticated","aud":"authenticated"}';

select throws_ok(
  $$ select public.resolve_match_dispute(
       (select id from public.match_disputes
         where match_id = public._tap_id('TT1 final') and status = 'open'),
       null, 'closed') $$,
  '22023', null, 'an unknown dispute status is refused');

select is(
  (select status from public.resolve_match_dispute(
     (select id from public.match_disputes
       where match_id = public._tap_id('TT1 final') and status = 'open'),
     null, 'under_review')),
  'under_review', 'the organizer can put a dispute under review without closing it');

select throws_ok(
  $$ select public.resolve_match_dispute(
       (select id from public.match_disputes
         where match_id = public._tap_id('TT1 final') and status = 'under_review'),
       null, 'resolved') $$,
  '22023', null, 'a resolved dispute must carry a resolution');

select ok(
  (select status = 'rejected' and resolution = 'log replay matches the published score'
          and resolved_at is not null
     from public.resolve_match_dispute(
       (select id from public.match_disputes
         where match_id = public._tap_id('TT1 final') and status = 'under_review'),
       'log replay matches the published score', 'rejected')),
  'rejecting a dispute keeps the published result and records why');

select is(
  (select status from public.raise_match_dispute(
     public._tap_id('TT1 final'), 'new evidence found in the point log')),
  'open', 'a closed dispute can be raised again on new evidence');

select is(
  (select count(*)::int from public.match_disputes
    where match_id = public._tap_id('TT1 final')),
  2, 'each dispute is kept as its own record');

select is(
  (select count(*)::int from public.match_lifecycle_log
    where match_id = public._tap_id('TT1 final')
      and action in ('dispute_raised', 'dispute_under_review', 'dispute_rejected')),
  4, 'every dispute step is audited, the second raise included');

select is(
  (select count(distinct action)::int from public.match_lifecycle_log
    where match_id = public._tap_id('TT1 final')
      and left(action, 8) = 'dispute_'),
  3, 'the audit trail distinguishes raised, under review and rejected');

select * from public.finish();
rollback;
